CREATE TABLE public.kid_devices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), parent_id uuid NOT NULL, name text NOT NULL, secret_hash text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), last_used_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT (now()+interval '180 days'), revoked_at timestamptz, child_id uuid, child_verified_at timestamptz, parent_unlocked_until timestamptz);
GRANT SELECT ON public.kid_devices TO authenticated;
GRANT ALL ON public.kid_devices TO service_role;
ALTER TABLE public.kid_devices ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Parent device list" ON public.kid_devices FOR SELECT TO authenticated USING (parent_id=auth.uid() AND public.is_active_parent() AND public.is_parent_device());
REVOKE SELECT ON public.kid_devices FROM authenticated;
GRANT SELECT(id,parent_id,name,created_at,last_used_at,expires_at,revoked_at) ON public.kid_devices TO authenticated;
CREATE TABLE public.kid_pairings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), parent_id uuid NOT NULL, code_hash text NOT NULL UNIQUE, proof_hash text NOT NULL UNIQUE, claim_hash text, device_name text, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT (now()+interval '10 minutes'), approved_at timestamptz, consumed_at timestamptz, device_id uuid);
GRANT ALL ON public.kid_pairings TO service_role;
ALTER TABLE public.kid_pairings ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.parent_device_pins (parent_id uuid PRIMARY KEY, pin_hash text NOT NULL, pin_salt text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.parent_device_pins TO service_role;
ALTER TABLE public.parent_device_pins ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.kid_auth_attempts (key text PRIMARY KEY, attempts integer NOT NULL DEFAULT 0, window_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.kid_auth_attempts TO service_role;
ALTER TABLE public.kid_auth_attempts ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.claim_kid_auth_attempt(_key text, _limit integer, _seconds integer) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.kid_auth_attempts; BEGIN INSERT INTO public.kid_auth_attempts(key,attempts,window_at) VALUES(_key,1,now()) ON CONFLICT(key) DO UPDATE SET attempts=CASE WHEN kid_auth_attempts.window_at < now()-make_interval(secs=>_seconds) THEN 1 ELSE kid_auth_attempts.attempts+1 END, window_at=CASE WHEN kid_auth_attempts.window_at < now()-make_interval(secs=>_seconds) THEN now() ELSE kid_auth_attempts.window_at END RETURNING * INTO r; RETURN r.attempts<=_limit; END $$;
REVOKE ALL ON FUNCTION public.claim_kid_auth_attempt(text,integer,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.claim_kid_auth_attempt(text,integer,integer) TO service_role;
CREATE FUNCTION public.consume_kid_pairing(_id uuid,_claim text,_secret text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.kid_pairings; d uuid; BEGIN SELECT * INTO r FROM public.kid_pairings WHERE id=_id AND claim_hash=_claim AND approved_at IS NOT NULL AND consumed_at IS NULL AND expires_at>now() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Pairing unavailable'; END IF; INSERT INTO public.kid_devices(parent_id,name,secret_hash) VALUES(r.parent_id,r.device_name,_secret) RETURNING id INTO d; UPDATE public.kid_pairings SET consumed_at=now(),device_id=d WHERE id=r.id; RETURN d; END $$;
REVOKE ALL ON FUNCTION public.consume_kid_pairing(uuid,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.consume_kid_pairing(uuid,text,text) TO service_role;